"""PED-17 Hạ đường huyết & Hạ thân nhiệt sơ sinh — nguồn duy nhất của thẻ."""


def r(x):
    return '<span style="color:#ff6b6b"><b>' + x + '</b></span>'


def y(x):
    return '<span style="color:#ffd43b"><b>' + x + '</b></span>'


def g(x):
    return '<span style="color:#51cf66"><b>' + x + '</b></span>'


def c(x):
    return '<span style="color:#74c0fc"><b>' + x + '</b></span>'


