_SECNO = {"B0": "0", "B1": "1", "B2": "2", "B3": "3", "B4": "4", "B5": "5", "B6": "6", "B7": "7",
          "B8": "8", "B9": "9", "B10": "10", "B11": "11", "B12": "12", "B13": "13", "B14": "14"}


def _src(sec):
    return "📖 Nguồn: Bài PED-17, phần " + _SECNO[sec] + " — " + _SEC[sec]


def bc(cid, sec, tier, cat, front, core, why, algo=False, extra=None, asks=None):
    body = "<br>".join(str(i + 1) + ") " + t for i, t in enumerate(core))
    back = ("<b>🎯 Trả lời cốt lõi:</b><br>" + body +
            "<br><br><b>💡 Giải thích của AI:</b><br>" + why)
    badge, bcls = _ALGO if algo else _EBM
    card = {"id": cid, "type": "basic", "track": "ebm", "section": sec, "category": cat, "tier": tier,
            "badge": badge, "badge_class": bcls, "front": front, "back": back,
            "extra": extra or _src(sec), "tags": ["PED-17", "ALGO" if algo else "EBM"]}
    if asks:
        card["asks"] = asks
    return card


# ---------------------------------------------------------------------------------------------
# TRACK 1 — BAREM GỐC (Hạ đường huyết sơ sinh, giáo trình Nhi khoa Y Thái Bình, trang 46 – 52).
# Nguồn đối chiếu: Ha_duong_huyet_so_sinh_PEDYTB.md (+ raw_cache/OCR_Ha_duong_huyet_so_sinh_VERBATIM.md).
# Section H0 – H5 = barem (track "barem_goc"); section B0 – B14 = EBM (track "ebm", gồm cả phần Hạ thân nhiệt).
# Con số khác barem trong thẻ EBM được ghi ở cuối 💡 (xem _XREF cuối file).
# ---------------------------------------------------------------------------------------------
_BAREM = ("🏛️ BAREM GỐC Y THÁI BÌNH", "badge-barem")

_HSEC = {
    "H0": "Barem — Đại cương hạ đường huyết sơ sinh",
    "H1": "Barem — Nguyên nhân hạ đường huyết sơ sinh",
    "H2": "Barem — Triệu chứng lâm sàng hạ đường huyết sơ sinh",
    "H3": "Barem — Cận lâm sàng & chẩn đoán phân biệt",
    "H4": "Barem — Điều trị hạ đường huyết sơ sinh",
    "H5": "Barem — Theo dõi, điều trị nguyên nhân, tiến triển & dự phòng",
}


def _hsrc(where):
    return "📖 Nguồn: Giáo trình Nhi khoa Y Thái Bình — Hạ đường huyết sơ sinh, " + where


def hb(cid, sec, tier, cat, front, core, why, where, ngoai=None, algo=False, asks=None):
    """Thẻ Basic barem gốc. `ngoai` = nội dung ngoài barem (EBM) đặt cuối 💡, có nhãn riêng."""
    body = "<br>".join(str(i + 1) + ") " + t for i, t in enumerate(core))
    note = ("<br><br><b>Ngoài barem:</b> " + ngoai) if ngoai else ""
    back = ("<b>🎯 Trả lời cốt lõi:</b><br>" + body +
            "<br><br><b>💡 Giải thích của AI:</b><br>" + why + note)
    badge, bcls = _ALGO if algo else _BAREM
    card = {"id": cid, "type": "basic", "track": "barem_goc", "section": sec, "category": cat, "tier": tier,
            "badge": badge, "badge_class": bcls, "front": front, "back": back,
            "extra": _hsrc(where), "tags": ["PED-17", "Barem-goc", "ALGO" if algo else "Ha-duong-huyet"]}
    if asks:
        card["asks"] = asks
    return card



