    bc("PED17-B8-04", "B8", 2, "Ủ ấm",
       "" + g("Bọc túi nhựa polyethylene") + " cho trẻ cực non: đối tượng, quy trình từng bước, cơ chế vật lý và bằng chứng Cochrane 2018 (số thử nghiệm, số trẻ, mức giảm hạ thân nhiệt)?",
       ["Đối tượng: tuổi thai " + y("< 32 tuần") + " hoặc cân nặng " + y("< 1500 g"),
        "Chuẩn bị túi sẵn trên bàn đón dưới máy sưởi bức xạ; " + r("TUYỆT ĐỐI KHÔNG LAU KHÔ THÂN TRẺ") + "; đặt vào túi, bọc kín từ cổ xuống chân, chỉ để lộ đầu; sau đó mới lau khô đầu và " + g("đội mũ ấm"),
        "Cơ chế: màng nhựa ngăn " + y("100%") + " bốc hơi nước ối, tạo vi khí hậu bão hòa ẩm, ngăn mất nhiệt đối lưu",
        "Cochrane 2018 (McCall): " + y("25 thử nghiệm, 3,433 trẻ") + " → giảm đáng kể hạ thân nhiệt lúc nhập viện (" + y("giảm 32%") + ", RR 0.68)"],
       "Lau khô trước khi bọc làm tróc biểu bì non nớt và mất 30 – 60 giây vàng, nhiệt bốc hơi dữ dội."),
