       ["SL4: trẻ non " + y("32.5°C") + " bị đặt túi nước nóng / vặn tối đa đèn sưởi → " + r("bỏng da, sốc giãn mạch, toan máu dội ngược từ các chi, ngừng tim đột ngột") + "; chuẩn: " + g("0.5 – 1.0°C/giờ dưới Servo-control, cảm biến da liên tục"),
        "SL5: trẻ " + y("28 tuần") + " được lau khô rồi mới vào túi → " + r("tróc biểu bì mỏng, mất 30 – 60 giây vàng, bốc hơi dữ dội") + "; chuẩn: " + g("không lau khô thân trẻ < 32 tuần, bọc túi kín từ cổ xuống chân ngay khi lọt lòng, chỉ lau khô đầu và đội mũ ấm")],
