        c("Seizure") + ": giật nhịp nhàng cơ học, " + y("xảy ra tự phát") + ", " + r("VẪN TIẾP TỤC GIẬT khi giữ chặt chi") + ", kèm đảo mắt, chép miệng liên tục, nhai tóp tép, ngưng thở, biến thiên nhịp tim",
