_seen = set()
for _card in cards_data:
    _note = _XREF.get(_card["id"])
    if not _note:
        continue
    _seen.add(_card["id"])
    if _card["type"] == "basic":
        _card["back"] += "<br><br>" + _XREF_HEAD + _note
    else:
        _card["text"] += "<br><b>⚖️ Ngoài barem:</b> " + _note
assert _seen == set(_XREF), "id _XREF không khớp thẻ: " + ", ".join(sorted(set(_XREF) - _seen))

